schemas.ddl:
CREATE TABLE `author` (
  `author_id` int NOT NULL,
  `full_name` varchar(100) NOT NULL,
  PRIMARY KEY (`author_id`)
) ENGINE=InnoDB;

CREATE TABLE `book` (
  `book_id` int NOT NULL,
  `title` varchar(200) NOT NULL,
  `author_id` int NOT NULL,
  PRIMARY KEY (`book_id`),
  CONSTRAINT `book_ibfk_1` FOREIGN KEY (`author_id`) REFERENCES `author` (`author_id`)
) ENGINE=InnoDB;

CREATE TABLE `order_line` (
  `order_id` int NOT NULL,
  `line_no` int NOT NULL,
  `sku` varchar(30) NOT NULL,
  PRIMARY KEY (`order_id`, `line_no`)
) ENGINE=InnoDB;

CREATE TABLE `shipment_item` (
  `shipment_id` int NOT NULL,
  `order_id` int NOT NULL,
  `line_no` int NOT NULL,
  PRIMARY KEY (`shipment_id`, `order_id`, `line_no`),
  CONSTRAINT `shipment_item_ibfk_1` FOREIGN KEY (`order_id`, `line_no`) REFERENCES `order_line` (`order_id`, `line_no`)
) ENGINE=InnoDB;

CREATE TABLE `patient` (
  `patient_id` int NOT NULL,
  `birth_year` int DEFAULT NULL,
  PRIMARY KEY (`patient_id`)
) ENGINE=InnoDB;

CREATE TABLE `visit` (
  `visit_id` int NOT NULL,
  `patient_id` int NOT NULL,
  `visit_date` date DEFAULT NULL,
  PRIMARY KEY (`visit_id`),
  CONSTRAINT `visit_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `patient` (`patient_id`)
) ENGINE=InnoDB;
